<?php $pageTitle='My Appointments';require __DIR__.'/header.php';?><h1>My Appointments</h1><section class="card table"><table><tr><th>Serial</th><th>Date</th><th>Time</th><th>Doctor</th><th>Department</th><th>Status</th><th>Action</th></tr><?php foreach($appointments as $a):?><tr><td>#<?=$a['serial_no']?></td><td><?=$a['appointment_date']?></td><td><?=date('g:i A',strtotime($a['appointment_time']))?></td><td>Dr. <?=htmlspecialchars($a['doctor_name'])?></td><td><?=htmlspecialchars($a['department_name'])?></td><td><span class="badge <?=$a['status']?>"><?=$a['status']?></span></td><td><?php if($a['status']==='pending'):?><a class="danger" href="index.php?action=cancel&id=<?=$a['id']?>" onclick="return confirm('Cancel this appointment?')">Cancel</a><?php endif;?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/footer.php';?>